def f():
    try:
        for i in [1, 2]:
            for j in [3, 4]:
                return (i, j)
    finally:
        print('finally')
print(f())

# multiple for loops and nested try-finally's
def f():
    try:
        for i in [1, 2]:
            for j in [3, 4]:
                try:
                    for k in [5, 6]:
                        for l in [7, 8]:
                            return (i, j, k, l)
                finally:
                    print('finally 2')
    finally:
        print('finally 1')
print(f())

