    try:
        for i in range(1, 3):
            for j in range(3, 5):
                try:
                    for k in range(5, 7):
                        for l in range(7, 9):
                            return (i, j, k, l)
                finally:
                    print('finally 2')
    finally:
        print('finally 1')
print(f())

